"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def sortWords(words):
    # Using a simple bubble sort for demonstration
    n = len(words)
    for i in range(0, n - 1):
        for j in range(0, n - i - 1):
            if (words[j] > words[(j + 1)]):
                temp_var = words[j]
                words[j] = words[(j + 1)]
                words[(j + 1)] = temp_var
    return words
print(sortWords(['This', 'is', 'a', 'sentence!']))
print(sortWords(['This', 'is', 'another', 'sentence.']))